INSERT INTO glossary_terms (term_key, term, aliases, definition, source, verified) VALUES
  ($g$pielonefritis$g$, $g$Pielonefritis$g$, ARRAY[$g$infeksi ginjal$g$]::text[], $g$Infeksi ginjal, yaitu jenis infeksi saluran kemih yang terjadi ketika infeksi dari kandung kemih naik melalui ureter ke satu atau kedua ginjal. Risikonya meningkat pada infeksi kandung kemih yang baru atau sedang berlangsung, sumbatan saluran kemih (misalnya batu ginjal atau pembesaran prostat), serta kondisi seperti diabetes, penyakit ginjal, dan penyakit sel sabit. Pada kasus yang jarang dapat menyebabkan gagal ginjal atau jaringan parut ginjal yang berlanjut menjadi penyakit ginjal kronik.$g$, $g$NIDDK (NIH) — Definition & Facts of Kidney Infection (Pyelonephritis); diringkas ke bahasa Indonesia$g$, false),
  ($g$sistitis$g$, $g$Sistitis$g$, ARRAY[$g$infeksi kandung kemih$g$,$g$radang kandung kemih$g$]::text[], $g$Peradangan kandung kemih, paling sering akibat infeksi bakteri yang masuk dan berkembang biak di kandung kemih. Ini jenis infeksi saluran kemih yang paling umum dan, bila tidak diobati, dapat berkembang menjadi infeksi ginjal. Pengobatannya umumnya dengan antibiotik.$g$, $g$NIDDK (NIH) — Bladder Infection (UTI) in Adults; NHS (nidirect) — Cystitis; diringkas ke bahasa Indonesia$g$, false),
  ($g$osteoartritis$g$, $g$Osteoartritis$g$, ARRAY[$g$OA$g$,$g$penyakit sendi degeneratif$g$,$g$osteoartrosis$g$]::text[], $g$Gangguan sendi yang terutama mengenai tulang rawan, yaitu jaringan keras namun licin yang menutupi ujung tulang pada sendi. Lapisan permukaan tulang rawan pecah dan aus, dengan gejala utama nyeri dan kaku sendi. Penyakit ini makin sering seiring usia, tetapi dapat muncul pada usia muda, biasanya setelah cedera sendi, kelainan bentuk sendi, atau cacat genetik pada tulang rawan.$g$, $g$NIAMS (NIH) — Handout on Health: Osteoarthritis; diringkas ke bahasa Indonesia$g$, false),
  ($g$prostatitis$g$, $g$Prostatitis$g$, ARRAY[$g$radang prostat$g$]::text[], $g$Peradangan kelenjar prostat dan kadang area di sekitarnya, yang sering menimbulkan nyeri. Menurut klasifikasi NIH, jenisnya meliputi prostatitis bakterial akut, prostatitis bakterial kronik, sindrom nyeri panggul kronik, dan prostatitis inflamasi tanpa gejala. Prostatitis tidak meningkatkan risiko kanker prostat, meskipun peradangan dapat menaikkan kadar PSA.$g$, $g$NIDDK (NIH) — Prostatitis: Inflammation of the Prostate; diringkas ke bahasa Indonesia$g$, false)
